/**
 * The corpus of the v0.3.0 re-verification: prompts written by the verifier
 * to attack the producer's reading of a request, each with the outcome a
 * careful listener would expect. Refinements start from the "bright" piece
 * (112 BPM, C major, piano, 30 s, loop) unless a case names another start.
 * tests/agent-rules.test.ts runs them and holds the safety metric over all
 * of them; what it leaves out, and why, is listed there.
 */
import type { StyleId } from "../../src/music/catalog";
import {
  DEFAULT_CONFIG,
  DEFAULT_VOLUMES,
  stylePreset,
} from "../../src/music/defaults";
import type { ArrangementHints, MusicConfig } from "../../src/types";

export type Move = number | "up" | "down" | "any";
export type Fader = Move | "off";
/** What a refinement must do; a parameter that is not named must stay as it was. */
export interface Want {
  bpm?: Move;
  dur?: Move;
  energy?: Move;
  complexity?: Move;
  reverb?: Move;
  key?: string | "any";
  lead?: string | "any" | "other";
  style?: string;
  loop?: boolean;
  melody?: Fader;
  chords?: Fader;
  bass?: Fader;
  drums?: Fader;
  seed?: true | "any";
  arr?: "any" | ((hints: ArrangementHints) => boolean);
  /** nothing may change */
  same?: true;
  says?: RegExp;
  notSays?: RegExp;
  from?: MusicConfig;
}

export const base = (
  style: StyleId = "bright",
  extra: Partial<MusicConfig> = {},
): MusicConfig => ({
  ...structuredClone(DEFAULT_CONFIG),
  ...stylePreset(style),
  prompt: "晴天散步",
  seed: 111,
  ...extra,
});
const muted = () =>
  base("bright", { volumes: { ...DEFAULT_VOLUMES, drums: 0 } });
const ending = () => base("bright", { loop: false });
const at = (patch: Partial<MusicConfig>) => base("bright", patch);
const pad = (hints: ArrangementHints) => hints.layers?.pad === true;

