type Range = number | [number, number];
/** What a new piece must be. */
export interface Expect {
  style?: string | string[];
  notStyle?: string[];
  bpm?: Range | "below" | "above" | "preset";
  dur?: Range;
  key?: string;
  minor?: boolean;
  lead?: string;
  notLead?: string[];
  loop?: boolean;
  drums?: "off" | "on" | "up" | "down";
  bass?: "off" | "on" | "up" | "down";
  melody?: "off" | "on";
  chords?: "off" | "on";
  energy?: [number, number] | "below" | "above";
  complexity?: "below" | "above";
  reverb?: "below" | "above";
  says?: RegExp;
  notSays?: RegExp;
}

